func weatherIcon(condition string) string {
	switch condition {
	case "sunny":
		return "☀️"
	case "partlycloudy":
		return "⛅"
	case "cloudy":
		return "☁️"
	case "rainy":
		return "🌧"
	case "pouring":
		return "🌧"
	case "snowy":
		return "🌨"
	case "fog":
		return "🌫"
	case "lightning":
		return "⛈"
	case "clear-night":
		return "🌙"
	case "windy":
		return "💨"
	default:
		return "☀️"
	}
}

